        int id = task->binsem_id[--task->binsem_num];
        binsem_node_t *node = &binsem_nodes[id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *heir_node = node->block_queue.next;
            pcb_t *heir = list_entry(heir_node, pcb_t, list);
            heir->binsem_id[heir->binsem_num++] = id;
            do_unblock(heir_node);
        }
    }
}

